<div class="form-layout"><div>
<section class="panel"><div class="panel-heading"><div><div class="eyebrow"><?= e(t('YOUR ACCOUNT')) ?></div><h2><?= e(t('Profile details')) ?></h2></div></div><form method="post" action="<?= e(url('profile')) ?>"><?= csrf_field() ?><div class="form-grid"><?php field('name',t('Name'),'text',$user['name'],'required maxlength="120" autocomplete="name"');field('email',t('Email address'),'email',$user['email'],'required maxlength="190" autocomplete="username"');field('current_password',t('Current password (required when changing email)'),'password','','autocomplete="current-password"'); ?></div><div class="form-footer"><span class="muted"><?= e(t('Your email address is used to sign in.')) ?></span><button class="button primary" type="submit"><?= e(t('Save profile')) ?></button></div></form></section>
<section class="panel"><div class="panel-heading"><div><div class="eyebrow"><?= e(t('ACCOUNT SECURITY')) ?></div><h2><?= e(t('Change password')) ?></h2></div></div><form method="post" action="<?= e(url('profile/password')) ?>"><?= csrf_field() ?><div class="form-grid"><?php field('current_password',t('Current password'),'password','','required autocomplete="current-password"');field('new_password',t('New password'),'password','','required minlength="10" maxlength="72" autocomplete="new-password"');field('password_confirmation',t('Confirm new password'),'password','','required minlength="10" maxlength="72" autocomplete="new-password"'); ?></div><div class="form-footer"><span class="muted"><?= e(t('Use 10–72 characters. Other sessions will be signed out.')) ?></span><button class="button primary" type="submit"><?= e(t('Change password')) ?></button></div></form></section>
